export function RhythmProvider({ children }: { children: ReactNode }) {
  const [habits, setHabits] = useState<Habit[]>([])
  const [completions, setCompletions] = useState<Set<string>>(new Set())
  const [moods, setMoods] = useState<MoodEntry[]>([])
