  useEffect(() => {
    let active = true
    loadSnapshot()
      .then((snapshot) => {
        if (!active) return
        setHabits(snapshot.habits)
        setCompletions(
          new Set(snapshot.completions.map((c) => `${c.habitId}|${c.date}`)),
        )
        setMoods(snapshot.moods)
      })
      .catch((error) => {
        console.error('Daten konnten nicht geladen werden', error)
      })
      .finally(() => {
        if (active) setLoading(false)
      })
    return () => {
      active = false
    }
