import puppeteer from 'puppeteer-core'

const CHROME =
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const URL = 'http://localhost:4173/'

const results = []
function check(name, ok, extra = '') {
  results.push({ name, ok, extra })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? '  — ' + extra : ''}`)
}

function parseColor(input) {
  const m = input.match(/rgba?\(([^)]+)\)/)
  if (!m) return null
  const [r, g, b] = m[1].split(',').map((n) => parseFloat(n))
  return [r / 255, g / 255, b / 255]
}
const lin = (c) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4))
const lum = (rgb) => {
  const [r, g, b] = rgb.map(lin)
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}
function ratio(a, b) {
  const l1 = lum(parseColor(a))
  const l2 = lum(parseColor(b))
  const hi = Math.max(l1, l2)
  const lo = Math.min(l1, l2)
  return (hi + 0.05) / (lo + 0.05)
}

async function clickText(page, text) {
  return page.evaluate((text) => {
    const els = [...document.querySelectorAll('button')]
    const el = els.find((e) => e.textContent.replace(/\s+/g, ' ').includes(text))
    if (!el) return false
    el.click()
    return true
  }, text)
}

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: 'new',
  args: ['--no-first-run', '--no-default-browser-check', '--disable-gpu'],
  defaultViewport: {
    width: 390,
    height: 844,
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
  },
})

const page = await browser.newPage()
const errors = []
page.on('console', (m) => {
  if (m.type() === 'error') errors.push(m.text())
})
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message))

await page.goto(URL, { waitUntil: 'networkidle0' })
await page.waitForSelector('h1')

// --- Basic render ---
const title = await page.title()
check('Titel ist Rhythm', title === 'Rhythm', title)
const lang = await page.evaluate(() => document.documentElement.lang)
check('Sprache ist de', lang === 'de', lang)
check('Manifest verlinkt', await page.evaluate(() => !!document.querySelector('link[rel="manifest"]')))
check('Theme-Color Meta vorhanden', await page.evaluate(() => !!document.querySelector('meta[name="theme-color"]')))

// --- Empty state ---
const emptyVisible = await page.evaluate(() =>
  document.body.innerText.includes('Noch ganz leer hier'),
)
check('Leerzustand ohne Habits sichtbar', emptyVisible)

// --- Add first habit ---
await page.click('button[aria-label="Neue Gewohnheit anlegen"]')
await page.waitForSelector('[role="dialog"]')
await page.type('#habit-name', 'Zehn Minuten lesen')
await page.evaluate(() => {
  const b = [...document.querySelectorAll('[role="dialog"] button')].find((e) =>
    e.getAttribute('aria-label')?.startsWith('Symbol'),
  )
  b?.click()
})
await page.evaluate(() => {
  document.querySelector('button[aria-label="Farbe Salbei"]')?.click()
})
await clickText(page, 'Hinzufügen')
await new Promise((r) => setTimeout(r, 400))
const firstAdded = await page.evaluate(() => document.body.innerText.includes('Zehn Minuten lesen'))
check('Erste Gewohnheit angelegt', firstAdded)

// --- Add second habit ---
await page.click('button[aria-label="Neue Gewohnheit anlegen"]')
await page.waitForSelector('[role="dialog"]')
await page.type('#habit-name', 'Wasser trinken')
await clickText(page, 'Hinzufügen')
await new Promise((r) => setTimeout(r, 400))
const secondAdded = await page.evaluate(() => document.body.innerText.includes('Wasser trinken'))
check('Zweite Gewohnheit angelegt', secondAdded)

// --- Rename (feature 2) ---
await clickText(page, 'Einstellungen')
await new Promise((r) => setTimeout(r, 300))
await page.click('button[aria-label="Zehn Minuten lesen bearbeiten"]')
await page.waitForSelector('[role="dialog"]')
await page.evaluate(() => {
  const input = document.querySelector('#habit-name')
  const setter = Object.getOwnPropertyDescriptor(
    window.HTMLInputElement.prototype,
    'value',
  ).set
  setter.call(input, 'Zwanzig Minuten lesen')
  input.dispatchEvent(new Event('input', { bubbles: true }))
})
await clickText(page, 'Speichern')
await new Promise((r) => setTimeout(r, 400))
const renamed = await page.evaluate(() => document.body.innerText.includes('Zwanzig Minuten lesen'))
check('Gewohnheit umbenannt', renamed)

// --- Back to today, toggle ---
await clickText(page, 'Heute')
await new Promise((r) => setTimeout(r, 300))
await page.click('button[aria-label^="Zwanzig Minuten lesen"]')
await new Promise((r) => setTimeout(r, 300))
const pressed = await page.evaluate(
  () => document.querySelector('button[aria-label^="Zwanzig Minuten lesen"]')?.getAttribute('aria-pressed'),
)
check('Habit abhakbar (aria-pressed=true)', pressed === 'true', `aria-pressed=${pressed}`)
const progress = await page.evaluate(() => document.body.innerText.includes('1 von'))
check('Fortschritt zeigt "1 von 2"', progress)
const streak = await page.evaluate(() => document.body.innerText.includes('Serie'))
check('Streak sichtbar am Habit', streak)

// --- Mood ---
await page.click('button[aria-label="Stimmung Gut"]')
await new Promise((r) => setTimeout(r, 300))
const noteAppears = await page.evaluate(() => !!document.querySelector('#mood-note'))
check('Kurznotiz erscheint nach Stimmungswahl', noteAppears)
await page.type('#mood-note', 'Produktiver Tag')
await page.evaluate(() => document.querySelector('#mood-note')?.blur())
await new Promise((r) => setTimeout(r, 300))

// --- Week screen ---
await clickText(page, 'Woche')
await new Promise((r) => setTimeout(r, 600))
const chart = await page.evaluate(() => !!document.querySelector('.recharts-surface'))
check('Wochen-Chart rendert', chart)
const weekStats = await page.evaluate(() => document.body.innerText.includes('Ø Stimmung'))
check('Wochen-Statistiken sichtbar', weekStats)
const chartPaths = await page.evaluate(
  () => document.querySelectorAll('.recharts-bar-rectangle, .recharts-line').length,
)
check('Chart enthält Balken und Linie', chartPaths >= 2, `${chartPaths} Serien`)

// --- Dark mode ---
await clickText(page, 'Einstellungen')
await new Promise((r) => setTimeout(r, 300))
await clickText(page, 'Dunkel')
await new Promise((r) => setTimeout(r, 300))
const darkOn = await page.evaluate(() => document.documentElement.classList.contains('dark'))
check('Dark Mode manuell umschaltbar', darkOn)
const storedTheme = await page.evaluate(() => localStorage.getItem('rhythm:theme'))
check('Theme-Auswahl gespeichert', storedTheme === 'dark', storedTheme)

// --- Contrast (dark) ---
async function tokenContrast(theme) {
  return page.evaluate(() => {
    const cs = getComputedStyle(document.documentElement)
    const pick = (name) => {
      const v = cs.getPropertyValue(name).trim()
      const d = document.createElement('div')
      d.style.color = v
      document.body.appendChild(d)
      const rgb = getComputedStyle(d).color
      d.remove()
      return rgb
    }
    return {
      ink: pick('--ink'),
      muted: pick('--muted'),
      faint: pick('--faint'),
      canvas: pick('--canvas'),
      surface: pick('--surface'),
      accent: pick('--accent'),
      accentStrong: pick('--accent-strong'),
      accentSoft: pick('--accent-soft'),
    }
  })
}
function reportContrast(label, t) {
  const pairs = [
    ['ink/canvas', t.ink, t.canvas, 4.5],
    ['ink/surface', t.ink, t.surface, 4.5],
    ['muted/canvas', t.muted, t.canvas, 4.5],
    ['muted/surface', t.muted, t.surface, 4.5],
    ['faint/canvas', t.faint, t.canvas, 4.5],
    ['faint/surface', t.faint, t.surface, 4.5],
    ['accent-strong/surface', t.accentStrong, t.surface, 4.5],
    ['accent-strong/soft', t.accentStrong, t.accentSoft, 4.5],
    ['accent/surface (grafik)', t.accent, t.surface, 3],
  ]
  for (const [name, a, b, min] of pairs) {
    const r = ratio(a, b)
    check(`${label} Kontrast ${name}`, r + 0.001 >= min, r.toFixed(2))
  }
}

const darkTokens = await tokenContrast()
reportContrast('Dark', darkTokens)

await clickText(page, 'Hell')
await new Promise((r) => setTimeout(r, 300))
const lightTokens = await tokenContrast()
reportContrast('Light', lightTokens)

// --- Touch targets ---
const small = await page.evaluate(() => {
  const out = []
  for (const el of document.querySelectorAll('button')) {
    const r = el.getBoundingClientRect()
    if (r.width === 0 && r.height === 0) continue
    if (r.height < 43.5 || r.width < 43.5) {
      out.push({
        label: (el.getAttribute('aria-label') || el.textContent || '').trim().slice(0, 30),
        w: Math.round(r.width),
        h: Math.round(r.height),
      })
    }
  }
  return out
})
check('Alle sichtbaren Touch-Ziele ≥ 44px', small.length === 0, JSON.stringify(small))

// --- PWA service worker ---
const sw = await page.evaluate(async () => {
  if (!('serviceWorker' in navigator)) return 'unsupported'
  const reg = await navigator.serviceWorker.ready
  return !!reg.active
})
check('Service Worker aktiv', sw === true, String(sw))

// --- Persistence ---
await clickText(page, 'Heute')
await new Promise((r) => setTimeout(r, 300))
await page.reload({ waitUntil: 'networkidle0' })
await page.waitForSelector('h1')
const persisted = await page.evaluate(
  () =>
    document.body.innerText.includes('Zwanzig Minuten lesen') &&
    document.body.innerText.includes('Produktiver Tag'),
)
check('Daten bleiben nach Reload erhalten', persisted)
const darkPersisted = await page.evaluate(() =>
  document.documentElement.classList.contains('dark'),
)
check('Hell-Auswahl bleibt nach Reload erhalten', darkPersisted === false)

// --- Offline ---
await page.setOfflineMode(true)
await page.reload({ waitUntil: 'domcontentloaded' })
await new Promise((r) => setTimeout(r, 800))
const offlineOk = await page.evaluate(
  () => document.body.innerText.includes('Zwanzig Minuten lesen'),
)
check('Offline nach Reload nutzbar (Daten sichtbar)', offlineOk)
await page.setOfflineMode(false)

// --- Delete habit (feature 2) ---
await clickText(page, 'Einstellungen')
await new Promise((r) => setTimeout(r, 300))
await page.click('button[aria-label="Wasser trinken bearbeiten"]')
await page.waitForSelector('[role="dialog"]')
await page.click('button[aria-label="Gewohnheit löschen"]')
await new Promise((r) => setTimeout(r, 200))
await clickText(page, 'Endgültig löschen')
await new Promise((r) => setTimeout(r, 400))
const deleted = await page.evaluate(() => !document.body.innerText.includes('Wasser trinken'))
check('Gewohnheit löschbar', deleted)

check('Keine Konsolenfehler', errors.length === 0, errors.slice(0, 3).join(' | '))

await browser.close()

const failed = results.filter((r) => !r.ok)
console.log(`\n${results.length - failed.length}/${results.length} Checks bestanden`)
if (failed.length) {
  console.log('FEHLGESCHLAGEN:')
  for (const f of failed) console.log(` - ${f.name} (${f.extra})`)
  process.exit(1)
}

import puppeteer from 'puppeteer-core'
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const URL = 'http://localhost:4173/'

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: 'new',
  args: ['--no-first-run', '--disable-gpu'],
  defaultViewport: { width: 390, height: 844, isMobile: true, hasTouch: true },
})
const page = await browser.newPage()
page.on('pageerror', (e) => console.log('PAGEERROR', e.message))
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text()) })

async function clickText(text) {
  return page.evaluate((text) => {
    const el = [...document.querySelectorAll('button')].find((e) =>
      e.textContent.replace(/\s+/g, ' ').includes(text),
    )
    el?.click()
    return !!el
  }, text)
}
async function dumpDB() {
  return page.evaluate(async () => {
    const req = indexedDB.open('rhythm')
    const db = await new Promise((res, rej) => {
      req.onsuccess = () => res(req.result)
      req.onerror = () => rej(req.error)
    })
    const read = (store) =>
      new Promise((res) => {
        const tx = db.transaction(store, 'readonly')
        const all = tx.objectStore(store).getAll()
        all.onsuccess = () => res(all.result)
      })
    const data = {
      habits: await read('habits'),
      completions: await read('completions'),
      moods: await read('moods'),
    }
    db.close()
    return data
  })
}

await page.goto(URL, { waitUntil: 'networkidle0' })
await page.waitForSelector('h1')

// add two habits
for (const name of ['Zehn Minuten lesen', 'Wasser trinken']) {
  await page.click('button[aria-label="Neue Gewohnheit anlegen"]')
  await page.waitForSelector('[role="dialog"]')
  await page.type('#habit-name', name)
  await clickText('Hinzufügen')
  await new Promise((r) => setTimeout(r, 300))
}
console.log('After adds:', JSON.stringify(await dumpDB(), null, 1))

// mood + note
await page.click('button[aria-label="Stimmung Gut"]')
await new Promise((r) => setTimeout(r, 200))
await page.type('#mood-note', 'Produktiver Tag')
await page.evaluate(() => document.querySelector('#mood-note').blur())
await new Promise((r) => setTimeout(r, 300))
console.log('After mood:', JSON.stringify(await dumpDB(), null, 1))

// reload
await page.reload({ waitUntil: 'networkidle0' })
await page.waitForSelector('h1')
await new Promise((r) => setTimeout(r, 500))
console.log('After reload db:', JSON.stringify(await dumpDB(), null, 1))
const text = await page.evaluate(() => document.body.innerText)
console.log('--- BODY TEXT ---\n' + text)
await browser.close()

