import puppeteer from 'puppeteer-core'
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const URL = 'http://localhost:4173/'

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: 'new',
  args: ['--no-first-run', '--disable-gpu'],
})

async function audit(width) {
  const page = await browser.newPage()
  await page.setViewport({ width, height: 800, isMobile: true, hasTouch: true })
  await page.goto(URL, { waitUntil: 'networkidle0' })
  await page.waitForSelector('h1')
  // add a habit so lists/cards are present
  await page.click('button[aria-label="Neue Gewohnheit anlegen"]')
  await page.waitForSelector('[role="dialog"]')
  await page.type('#habit-name', 'Ein ziemlich langer Gewohnheitsname zum Testen')
  const modalOk = await page.evaluate(() => {
    const d = document.querySelector('[role="dialog"]')
    return d.getBoundingClientRect().width <= window.innerWidth
  })
  await page.evaluate(() => {
    // close dialog
    document.querySelector('[role="dialog"]')
      ?.parentElement?.querySelector('button[aria-label="Schließen"]')
      ?.click()
  })
  await new Promise((r) => setTimeout(r, 300))
  const data = await page.evaluate(() => {
    const de = document.documentElement
    const main = document.querySelector('main')
    const mainRect = main.getBoundingClientRect()
    return {
      scrollWidth: de.scrollWidth,
      innerWidth: window.innerWidth,
      bodyOverflowX: getComputedStyle(document.body).overflowX,
      mainLeft: Math.round(mainRect.left),
      mainRight: Math.round(mainRect.right),
      mainWidth: Math.round(mainRect.width),
      canvasBg: getComputedStyle(document.body).backgroundColor,
    }
  })
  await page.close()
  return { width, modalOk, ...data }
}

for (const w of [320, 375, 414, 768]) {
  const r = await audit(w)
  const overflow = r.scrollWidth > r.innerWidth + 1
  console.log(
    `w=${String(w).padEnd(4)} overflow=${overflow ? 'YES(' + r.scrollWidth + ')' : 'no'} modalFits=${r.modalOk} main=[${r.mainLeft}..${r.mainRight}] width=${r.mainWidth} bg=${r.canvasBg}`,
  )
}

// dark mode applied check
const page = await browser.newPage()
await page.setViewport({ width: 375, height: 800, isMobile: true })
await page.goto(URL, { waitUntil: 'networkidle0' })
await page.waitForSelector('h1')
await page.evaluate(() => {
  const el = [...document.querySelectorAll('button')].find((b) =>
    b.textContent.includes('Einstellungen'),
  )
  el.click()
})
await new Promise((r) => setTimeout(r, 300))
await page.evaluate(() => {
  const el = [...document.querySelectorAll('button')].find((b) =>
    b.textContent.trim() === 'Dunkel',
  )
  el.click()
})
await new Promise((r) => setTimeout(r, 300))
const dark = await page.evaluate(() => ({
  hasClass: document.documentElement.classList.contains('dark'),
  bodyBg: getComputedStyle(document.body).backgroundColor,
  bodyColor: getComputedStyle(document.body).color,
  reduced: window.matchMedia('(prefers-reduced-motion: reduce)').matches,
}))
console.log('dark applied:', JSON.stringify(dark))

// reduced motion check via emulation
await page.emulateMediaFeatures([
  { name: 'prefers-reduced-motion', value: 'reduce' },
])
const rm = await page.evaluate(() => {
  const el = document.querySelector('.animate-rise')
  if (!el) return 'no .animate-rise'
  return getComputedStyle(el).animationDuration
})
console.log('reduced-motion animationDuration:', rm)

await browser.close()

